=== width: 100vw 使用箇所 ===

100vw出現数: 0

=== -webkit-line-clamp（テキスト自動省略） ===
使用あり: True
  :vertical;-webkit-line-clamp:1;
  :vertical;-webkit-line-clamp:2;

=== position: fixed / sticky (追従バナー候補) ===
件数: 5
  .cover{width:100%;height:100%;max-width:none;position:fixed;top:0;left:0;text-align:center;margin:auto}
  .l-header{width:100%;padding:15px 0;position:fixed;top:0;left:0;z-index:100;transition:.3s ease}
  .l-nav{display:none;width:100%;max-width:568px;position:fixed;z-index:100;height:100vh;right:0;top:0;background:#f6f5f5;padding:15px 20px 80px}
  .toggle_active{z-index:999;position:fixed;top:20px;right:20px;transform:translateY(0)}
  .drawer_bg{display:none;width:100%;height:100%;position:fixed;z-index:99;top:0;left:0;background-color:rgba(51,51,51,.5)}

=== a:hover でopacityのみのルール ===
a:hover等ルール総数: 21
opacityのみ: 7
  a:hover{opacity:.7}
  a:hover img{opacity:.7}
  input[type=submit].input_submit:hover,input[type=reset].input_submit:hover,input[type=button].input_submit:hover,button[type=submit].input_submit:hove
  .l-header.is-change .l-header__logo:hover{opacity:.5}
  .l-header.is-change .l-header__nav__list li a:hover{opacity:.5}
  .l-footer__logo:hover{opacity:.5}
  .p-editor .wp-block-button a:hover{opacity:.8}

=== overflow-x ===
  line-height:1;text-transform:capitalize;overflow-x:auto;

