--- l-footer__nav ---
--- l-footer__logo ---
  .l-footer__logo{display:inline-flex;justify-content:flex-start;align-items:flex-end}
  .l-footer__logo:hover{opacity:.5}
  .l-footer__logo__img{margin-bottom:3px;margin-right:9px}
  .l-footer__logo__img{margin-bottom:2px;margin-right:7px;width:29px;height:35px}
  .l-footer__logo__text{color:#191818;display:flex;width:214px;height:41px;transition:.3s ease}
  .l-footer__logo__text{width:166px;height:32px}
  .l-footer__logo__text path{fill:currentColor}
--- c-articleList ---
  .c-articleList{width:100%;max-width:890px;margin-inline:auto}
  .c-articleList__item{border-bottom:1px solid #e3e3e3}
  .c-articleList__link{display:flex;align-items:center;background-image:url(../img/arrow/arrow_right.svg);background-repeat:no-repeat;background-size:7p
  .c-articleList__link{flex-wrap:wrap;padding:20px 20px 20px 0}
  .c-articleList__date{width:120px;font-size:18px;font-weight:500;letter-spacing:0;line-height:1;margin-right:10px}
  .c-articleList__date{width:110px}
  .c-articleList__cat{display:block;width:120px;margin-right:10px}
  .c-articleList__cat{width:auto}
  .c-articleList__cat a,.c-articleList__cat span{height:32px;display:inline-grid;place-items:center;background-color:#d62c05;color:#fff;padding:0 10px 2
  .c-articleList__cat a,.c-articleList__cat a:hover,.c-articleList__cat a:visited,.c-articleList__cat a:link,.c-articleList__cat span,.c-articleList__ca
  .c-articleList__ttl{flex:1;font-size:16px;font-weight:400;letter-spacing:0;line-height:1.6875;overflow:hidden;max-height:1.6875;line-height:1.6875}
  .c-articleList__ttl .textline{display:-webkit-box;-webkit-box-orient:vertical;-webkit-line-clamp:1;line-height:1.6875}
  .c-articleList__ttl{flex:0 0 100%;font-size:14px;line-height:1.5714285714;overflow:hidden;max-height:3.1428571429;line-height:1.5714285714;margin-top:
  .c-articleList__ttl .textline{display:-webkit-box;-webkit-box-orient:vertical;-webkit-line-clamp:2;line-height:1.5714285714}
--- l-header__logo\b ---
  .l-header__logo{display:flex;justify-content:flex-start;align-items:flex-end}
  .l-header__logo.--nav{display:none}
  .l-header__logo:hover{opacity:.5}

